package com.taskmanager.exception;import jakarta.persistence.EntityNotFoundException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.security.authentication.BadCredentialsException;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(EntityNotFoundException.class)ResponseEntity<?> notFound(Exception e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> conflict(Exception e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}@ExceptionHandler(BadCredentialsException.class)ResponseEntity<?> credentials(){return ResponseEntity.status(401).body(Map.of("message","Email or password is incorrect"));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("message","Please check the submitted fields","errors",errors));}}
